  confirmStatus: ConfirmButtonTransitionState;
  removeStatus: ConfirmButtonTransitionState;
  onConfirm: (discount: OrderDiscountCommonInput) => void;
  onRemove: () => void;
  onClose: () => void;
  title: ReactNode;
  description?: ReactNode;
  wrapDescription?: boolean;
  preFormContent?: ReactNode;
}

export const DiscountModalBase = ({
  open,
  maxPrice,
  existingDiscount,
  confirmStatus,
  removeStatus,
  onConfirm,
  onRemove,
  onClose,
  title,
  description,
  wrapDescription = true,
  preFormContent,
}: DiscountModalBaseProps) => {
  const intl = useIntl();

  const {
    control,
    valueFieldSymbol,
    valueErrorMsg,
    isSubmitDisabled,
    getDiscountData,
    onCalculationModeChange,
  } = useDiscountForm({
    maxPrice,
    existingDiscount,
    isOpen: open,
  });

  const handleConfirm = () => {
    onConfirm(getDiscountData());
  };

  return (
    <DashboardModal open={open} onChange={onClose}>
      <DashboardModal.Content size="xs">
        <DashboardModal.ContextHeader description={description} wrapDescription={wrapDescription}>
          {title}
